import java.util.*;

class Solution {
    public List<String> braceExpansionII(String expression) {
            Stack<Character> opStack = new Stack<>();
                    Stack<Set<String>> valStack = new Stack<>();

                            StringBuilder sb = new StringBuilder();
                                    for (int i = 0; i < expression.length(); i++) {
                                                char c = expression.charAt(i);
                                                            sb.append(c);
                                                                        if (i + 1 < expression.length()) {
                                                                                        char next = expression.charAt(i + 1);
                                                                                                        if ((Character.isLetter(c) || c == '}') && (Character.isLetter(next) || next == '{')) {
                                                                                                                            sb.append('*');
                                                                                                                                            }
                                                                                                                                                        }
                                                                                                                                                                }
                                                                                                                                                                        String expr = sb.toString();

                                                                                                                                                                                for (int i = 0; i < expr.length(); i++) {
                                                                                                                                                                                            char c = expr.charAt(i);

                                                                                                                                                                                                        if (Character.isLetter(c)) {
                                                                                                                                                                                                                        Set<String> set = new HashSet<>();
                                                                                                                                                                                                                                        set.add(String.valueOf(c));
                                                                                                                                                                                                                                                        valStack.push(set);
                                                                                                                                                                                                                                                                    } else if (c == '{') {
                                                                                                                                                                                                                                                                                    opStack.push(c);
                                                                                                                                                                                                                                                                                                } else if (c == '}') {
                                                                                                                                                                                                                                                                                                                while (!opStack.isEmpty() && opStack.peek() != '{') {
                                                                                                                                                                                                                                                                                                                                    evaluate(opStack, valStack);
                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                    opStack.pop();
                                                                                                                                                                                                                                                                                                                                                                                } else if (c == ',' || c == '*') {
                                                                                                                                                                                                                                                                                                                                                                                                while (!opStack.isEmpty() && opStack.peek() != '{' && precedence(opStack.peek()) >= precedence(c)) {
                                                                                                                                                                                                                                                                                                                                                                                                                    evaluate(opStack, valStack);
                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                    opStack.push(c);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                while (!opStack.isEmpty()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            evaluate(opStack, valStack);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            List<String> result = new ArrayList<>(valStack.pop());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Collections.sort(result);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return result;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    private int precedence(char op) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (op == '*') return 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (op == ',') return 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    private void evaluate(Stack<Character> opStack, Stack<Set<String>> valStack) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            char op = opStack.pop();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Set<String> set2 = valStack.pop();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Set<String> set1 = valStack.pop();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Set<String> res = new HashSet<>();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (op == '*') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (String s1 : set1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (String s2 : set2) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            res.add(s1 + s2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else if (op == ',') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            res.addAll(set1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        res.addAll(set2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        valStack.push(res);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }